/* @lc app=leetcode id=3380 lang=kotlin */ class Solution { fun maxRectangleArea(points: Array<IntArray>): Int = points.map { it[0] to it[1] }.toSet().let { st -> points.flatMap { p -> points.filter { q -> q[0] > p[0] && q[1] > p[1] && (p[0] to q[1]) in st && (q[0] to p[1]) in st && points.none { r -> r[0] in p[0]..q[0] && r[1] in p[1]..q[1] && !((r[0] == p[0] || r[0] == q[0]) && (r[1] == p[1] || r[1] == q[1])) } }.map { q -> (q[0] - p[0]) * (q[1] - p[1]) } }.maxOrNull() ?: -1 } }